mapper.select:
select DISTINCT stationname,stationid from dbtoms.StationCode

    stationid in

        #{id}

select vehicleclass,vehiclename from dbtoms.tbvehicleclass

    vehicleclass in

        #{id}

SELECT SUM(a.TotalFee) AS dueAmount, SUM(a.TotalArrearage) AS arrearsAmount, SUM(CASE WHEN a.TotalArrearage is not NULL AND a.TotalArrearage != 0 THEN a.CarNum ELSE 0 END) AS arrearsTrips, SUM(CASE WHEN a.PayType = 16 THEN a.TotalToll ELSE 0 END) AS mobilePaymentAmount, SUM(CASE WHEN a.PayType = 2 THEN a.TotalToll ELSE 0 END) AS ePaymentAmount FROM `tbstatexit` a
AND a.StationID = #{stationId}
AND a.StaDate = #{statisticsTime}
AND a.ShiftID = #{shiftId}
GROUP BY OperatorID

SELECT SUM(a.TotalFee) AS dueAmount, SUM(a.TotalArrearage) AS arrearsAmount, SUM(CASE WHEN a.TotalArrearage is not NULL AND a.TotalArrearage != 0 THEN a.CarNum ELSE 0 END) AS arrearsTrips, SUM(CASE WHEN a.PayType = 16 THEN a.TotalToll ELSE 0 END) AS mobilePaymentAmount, SUM(CASE WHEN a.PayType = 2 THEN a.TotalToll ELSE 0 END) AS ePaymentAmount FROM `tbstatexit` a
AND a.StationID = #{stationId}
AND a.StaDate = #{time}
AND a.ShiftID = #{shiftId}
GROUP BY OperatorID ORDER BY item.ShiftID ASC

SELECT
SUM(HandToll) AS handToll,
SUM(AddedToll) AS addedToll
FROM `tbsh`


        AND a.StationID = #{stationId}


        AND a.StaDate = #{time}


        AND a.ShiftID = #{shiftId}


GROUP BY OperatorID

SELECT a.StationID AS stationId, (SELECT stationname FROM dbtoms.tbstationinfo WHERE a.StationID = stationid LIMIT 1 ) AS stationName, LEFT(a.StaDate, 6) AS monthDate, a.StaDate AS staDate, IFNULL(SUM(CASE WHEN a.VehicleStatus IN (1,51,52) AND a.DealStatus&14=10 THEN a.CarNum ELSE 0 END),0) jzx, IFNULL(SUM(CASE WHEN a.VehicleStatus=101 AND a.DealStatus&14=10 THEN a.CarNum ELSE 0 END),0) yz, IFNULL(SUM(CASE WHEN a.VehicleStatus=102 AND a.DealStatus&14=10 THEN a.CarNum ELSE 0 END),0) ls, IFNULL(SUM(CASE WHEN a.VehicleStatus=104 AND a.DealStatus&14=10 THEN a.CarNum ELSE 0 END),0) kz, IFNULL(SUM(CASE WHEN a.VehicleStatus=107 AND a.DealStatus&14=10 THEN a.CarNum ELSE 0 END),0) jg, IFNULL(SUM(CASE WHEN a.VehicleStatus=105 AND (a.DealStatus&14=2 OR a.PayType=2) THEN a.CarNum ELSE 0 END),0) yg, IFNULL(SUM(CASE WHEN a.DealStatus&14=8 THEN a.CarNum ELSE 0 END),0) jc, IFNULL(SUM(CASE WHEN a.DealStatus&14=6 AND a.DealStatus&16777216=16777216 THEN a.CarNum ELSE 0 END),0) zy, IFNULL(SUM(CASE WHEN a.DealStatus&14=10 AND a.VehicleStatus=106 THEN a.CarNum ELSE 0 END),0) sgj, IFNULL(SUM(CASE WHEN a.DealStatus&14=10 AND a.VehicleStatus=111 THEN a.CarNum ELSE 0 END),0) zobl, IFNULL(SUM(CASE WHEN a.DealStatus&14=10 AND a.VehicleStatus=26 THEN a.CarNum ELSE 0 END),0) yj, IFNULL(SUM(CASE WHEN a.DealStatus&14=10 AND a.VehicleStatus=212 THEN a.CarNum ELSE 0 END),0) djys FROM
SELECT * FROM ${tableName} AS alias${index + 1}
AND CancelFlag = 0 AND SUBSTRING(LaneID,-3,1)=1 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
ORDER BY StaDate ASC
ORDER BY monthDate ASC
ORDER BY StationID ASC

SELECT a.StationID AS stationId, (SELECT stationname FROM dbtoms.tbstationinfo WHERE a.StationID = stationid LIMIT 1 ) AS stationName, IFNULL(SUM(CASE WHEN a.VehicleClass=1 THEN a.CarNum ELSE 0 END),0) AS k1, IFNULL(SUM(CASE WHEN a.VehicleClass=2 THEN a.CarNum ELSE 0 END),0) AS k2, IFNULL(SUM(CASE WHEN a.VehicleClass=3 THEN a.CarNum ELSE 0 END),0) AS k3, IFNULL(SUM(CASE WHEN a.VehicleClass=4 THEN a.CarNum ELSE 0 END),0) AS k4, IFNULL(SUM(CASE WHEN a.VehicleClass < 10 THEN a.CarNum ELSE 0 END),0) AS kSum IFNULL(SUM(CASE WHEN a.VehicleClass=11 THEN a.CarNum ELSE 0 END),0) AS h1, IFNULL(SUM(CASE WHEN a.VehicleClass=12 THEN a.CarNum ELSE 0 END),0) AS h2, IFNULL(SUM(CASE WHEN a.VehicleClass=13 THEN a.CarNum ELSE 0 END),0) AS h3, IFNULL(SUM(CASE WHEN a.VehicleClass=14 THEN a.CarNum ELSE 0 END),0) AS h4, IFNULL(SUM(CASE WHEN a.VehicleClass=15 THEN a.CarNum ELSE 0 END),0) AS h5, IFNULL(SUM(CASE WHEN a.VehicleClass=16 THEN a.CarNum ELSE 0 END),0) AS h6, IFNULL(SUM(CASE WHEN (a.VehicleClass > 10 AND a.VehicleClass < 20 THEN a.CarNum ELSE 0 END),0) AS hSum, IFNULL(SUM(CASE WHEN a.VehicleClass=21 THEN a.CarNum ELSE 0 END),0) z1, IFNULL(SUM(CASE WHEN a.VehicleClass=22 THEN a.CarNum ELSE 0 END),0) z2, IFNULL(SUM(CASE WHEN a.VehicleClass=23 THEN a.CarNum ELSE 0 END),0) z3, IFNULL(SUM(CASE WHEN a.VehicleClass=24 THEN a.CarNum ELSE 0 END),0) z4, IFNULL(SUM(CASE WHEN a.VehicleClass=25 THEN a.CarNum ELSE 0 END),0) z5, IFNULL(SUM(CASE WHEN a.VehicleClass=26 THEN a.CarNum ELSE 0 END),0) z6, IFNULL(SUM(CASE WHEN (a.VehicleClass > 20 AND a.VehicleClass < 30 THEN a.CarNum ELSE 0 END),0) zSum FROM
SELECT * FROM ${tableName} AS alias${index + 1}
AND StationID = #{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a

SELECT a.StationID AS stationId, (SELECT stationname FROM dbtoms.tbstationinfo WHERE a.StationID = stationid LIMIT 1 ) AS stationName, LEFT(a.StaDate, 6) AS monthDate, a.StaDate AS staDate, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND substring(a.LaneID,-4,1)=0 AND CardType not IN (22,23) THEN a.CarNum ELSE 0 END),0) rxj, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND substring(a.LaneID,-4,1)=0 AND a.cardtype in(22,23) AND a.dealstatus&14=2 THEN a.CarNum ELSE 0 END),0) rdz, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND substring(a.LaneID,-4,1)=0 AND a.dealstatus&14=6 THEN a.CarNum ELSE 0 END),0) rgw, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND substring(a.LaneID,-4,1)=0 AND a.dealstatus&14=8 THEN a.CarNum ELSE 0 END),0) rjc, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND substring(a.LaneID,-4,1)=0 AND a.dealstatus&14=10 THEN a.CarNum ELSE 0 END),0) ryh, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND substring(a.LaneID,-4,1)=0 AND a.dealstatus&14=14 THEN a.CarNum ELSE 0 END),0) rcd, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND substring(a.LaneID,-4,1)=0 AND a.PayType=0 THEN a.CarNum ELSE 0 END),0) cxj, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND substring(a.LaneID,-4,1)=0 AND a.PayType=2 THEN a.CarNum ELSE 0 END),0) cdz, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND substring(a.LaneID,-4,1)=0 AND a.PayType=16 THEN a.CarNum ELSE 0 END),0) cyd, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND substring(a.LaneID,-4,1)=0 AND a.dealstatus&14=6 THEN a.CarNum ELSE 0 END),0) cgw, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND substring(a.LaneID,-4,1)=0 AND a.dealstatus&14=8 THEN a.CarNum ELSE 0 END),0) cjc, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND substring(a.LaneID,-4,1)=0 AND a.dealstatus&14=10 THEN a.CarNum ELSE 0 END),0) cyh, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND substring(a.LaneID,-4,1)=0 AND a.dealstatus&14=12 THEN a.CarNum ELSE 0 END),0) cmf, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND substring(a.LaneID,-4,1)=0 AND a.dealstatus&14=14 THEN a.CarNum ELSE 0 END),0) ccd FROM
SELECT StationID,LaneID,StaDate,VehicleClass,CarNum,VehicleStatus,DealStatus,NULL AS PayType,CardType FROM tbstatentry${month} AS alias${index + 1}
AND CancelFlag = 0 AND RecordType &3=3 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
UNION ALL SELECT StationID,LaneID,StaDate,VehicleClass,CarNum,VehicleStatus,DealStatus,PayType,CardType FROM tbstatexit${month} AS alias${index + 1}
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
ORDER BY StaDate ASC
ORDER BY monthDate ASC
ORDER BY StationID ASC

SELECT a.StationID AS stationId, (SELECT stationname FROM dbtoms.tbstationinfo WHERE a.StationID = stationid LIMIT 1 ) AS stationName, LEFT(a.StaDate, 6) AS monthDate, a.StaDate AS staDate, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND a.dealstatus&14=0 THEN a.CarNum ELSE 0 END),0) rxj, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND a.cardtype in(22,23) THEN a.CarNum ELSE 0 END),0) rdz, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND a.dealstatus&14=6 THEN a.CarNum ELSE 0 END),0) rgw, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND a.dealstatus&14=8 THEN a.CarNum ELSE 0 END),0) rjc, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND a.dealstatus&14=10 THEN a.CarNum ELSE 0 END),0) ryh, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND a.dealstatus&14=14 THEN a.CarNum ELSE 0 END),0) rcd, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND a.PayType=0 THEN a.CarNum ELSE 0 END),0) cxj, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND a.PayType=2 THEN a.CarNum ELSE 0 END),0) cdz, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND a.PayType=16 THEN a.CarNum ELSE 0 END),0) cyd, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND a.dealstatus&14=6 THEN a.CarNum ELSE 0 END),0) cgw, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND a.dealstatus&14=8 THEN a.CarNum ELSE 0 END),0) cjc, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND a.dealstatus&14=10 THEN a.CarNum ELSE 0 END),0) cyh, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND a.dealstatus&14=12 THEN a.CarNum ELSE 0 END),0) cmf, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND a.dealstatus&14=14 THEN a.CarNum ELSE 0 END),0) ccd FROM
SELECT StationID,LaneID,StaDate,VehicleClass,CarNum,VehicleStatus,DealStatus,NULL AS PayType,CardType FROM tbstatentry${month} AS alias${index + 1}
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
UNION ALL SELECT StationID,LaneID,StaDate,VehicleClass,CarNum,VehicleStatus,DealStatus,PayType,CardType FROM tbstatexit${month} AS alias${index + 1}
AND CancelFlag = 0 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate
GROUP BY monthDate
GROUP BY StationID
ORDER BY StaDate ASC
ORDER BY monthDate ASC
ORDER BY StationID ASC

SELECT a.StationID AS stationId, (SELECT StationName FROM dbtoms.tbstationinfo WHERE a.StationID = StationID LIMIT 1) AS stationName, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=1 OR a.VehicleClass=11) THEN a.CarNum ELSE 0 END),0) AS r1, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=2 OR a.VehicleClass=12) THEN a.CarNum ELSE 0 END),0) AS r2, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=3 OR a.VehicleClass=13) THEN a.CarNum ELSE 0 END),0) AS r3, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=4 OR a.VehicleClass=14) THEN a.CarNum ELSE 0 END),0) AS r4, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=5 OR a.VehicleClass=15) THEN a.CarNum ELSE 0 END),0) AS r5, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=6 OR a.VehicleClass=16) THEN a.CarNum ELSE 0 END),0) AS r6, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass IN (21,22,23,24,25,26)) THEN a.CarNum ELSE 0 END),0) AS rzx, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=1 OR a.VehicleClass=11) THEN a.CarNum ELSE 0 END),0) AS c1, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=2 OR a.VehicleClass=12) THEN a.CarNum ELSE 0 END),0) AS c2, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=3 OR a.VehicleClass=13) THEN a.CarNum ELSE 0 END),0) AS c3, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=4 OR a.VehicleClass=14) THEN a.CarNum ELSE 0 END),0) AS c4, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=5 OR a.VehicleClass=15) THEN a.CarNum ELSE 0 END),0) AS c5, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=6 OR a.VehicleClass=16) THEN a.CarNum ELSE 0 END),0) AS c6, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass IN (21,22,23,24,25,26)) THEN a.CarNum ELSE 0 END),0) AS czx FROM
SELECT * FROM ${tableName} AS alias${index + 1}
AND CancelFlag = 0
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a GROUP BY a.StationID ORDER BY a.StationID

SELECT a.StationID AS stationId, (SELECT StationName FROM dbtoms.tbstationinfo WHERE a.StationID = StationID LIMIT 1) AS stationName, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=1 OR a.VehicleClass=11) THEN a.CarNum ELSE 0 END),0) AS r1, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=2 OR a.VehicleClass=12) THEN a.CarNum ELSE 0 END),0) AS r2, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=3 OR a.VehicleClass=13) THEN a.CarNum ELSE 0 END),0) AS r3, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=4 OR a.VehicleClass=14) THEN a.CarNum ELSE 0 END),0) AS r4, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=5 OR a.VehicleClass=15) THEN a.CarNum ELSE 0 END),0) AS r5, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass=6 OR a.VehicleClass=16) THEN a.CarNum ELSE 0 END),0) AS r6, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=0 AND (a.VehicleClass IN (21,22,23,24,25,26)) THEN a.CarNum ELSE 0 END),0) AS rzx, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=1 OR a.VehicleClass=11) THEN a.CarNum ELSE 0 END),0) AS c1, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=2 OR a.VehicleClass=12) THEN a.CarNum ELSE 0 END),0) AS c2, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=3 OR a.VehicleClass=13) THEN a.CarNum ELSE 0 END),0) AS c3, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=4 OR a.VehicleClass=14) THEN a.CarNum ELSE 0 END),0) AS c4, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=5 OR a.VehicleClass=15) THEN a.CarNum ELSE 0 END),0) AS c5, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass=6 OR a.VehicleClass=16) THEN a.CarNum ELSE 0 END),0) AS c6, IFNULL(SUM(CASE WHEN substring(a.LaneID,-3,1)=1 AND (a.VehicleClass IN (21,22,23,24,25,26)) THEN a.CarNum ELSE 0 END),0) AS czx FROM
SELECT * FROM ${tableName} AS alias${index + 1}
AND CancelFlag = 0
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a GROUP BY a.StationID ORDER BY a.StationID

SELECT a.StationID AS stationId, (SELECT stationname FROM dbtoms.tbstationinfo WHERE a.StationID = stationid LIMIT 1 ) AS stationName, a.StaDate AS staDate, LEFT(a.StaDate, 6) AS monthDate, IFNULL(SUM(CASE WHEN a.VehicleClass=1 THEN a.CarNum ELSE 0 END),0) k1, IFNULL(SUM(CASE WHEN a.VehicleClass=2 THEN a.CarNum ELSE 0 END),0) k2, IFNULL(SUM(CASE WHEN a.VehicleClass=3 THEN a.CarNum ELSE 0 END),0) k3, IFNULL(SUM(CASE WHEN a.VehicleClass=4 THEN a.CarNum ELSE 0 END),0) k4, IFNULL(SUM(CASE WHEN a.VehicleClass IN (1,2,3,4) THEN a.CarNum ELSE 0 END),0) ksum, IFNULL(SUM(CASE WHEN a.VehicleClass=11 THEN a.CarNum ELSE 0 END),0) h1, IFNULL(SUM(CASE WHEN a.VehicleClass=12 THEN a.CarNum ELSE 0 END),0) h2, IFNULL(SUM(CASE WHEN a.VehicleClass=13 THEN a.CarNum ELSE 0 END),0) h3, IFNULL(SUM(CASE WHEN a.VehicleClass=14 THEN a.CarNum ELSE 0 END),0) h4, IFNULL(SUM(CASE WHEN a.VehicleClass=15 THEN a.CarNum ELSE 0 END),0) h5, IFNULL(SUM(CASE WHEN a.VehicleClass=16 THEN a.CarNum ELSE 0 END),0) h6, IFNULL(SUM(CASE WHEN a.VehicleClass IN (11,12,13,14,15,16) THEN a.CarNum ELSE 0 END),0) hsum, IFNULL(SUM(CASE WHEN a.VehicleClass=21 THEN a.CarNum ELSE 0 END),0) z1, IFNULL(SUM(CASE WHEN a.VehicleClass=22 THEN a.CarNum ELSE 0 END),0) z2, IFNULL(SUM(CASE WHEN a.VehicleClass=23 THEN a.CarNum ELSE 0 END),0) z3, IFNULL(SUM(CASE WHEN a.VehicleClass=24 THEN a.CarNum ELSE 0 END),0) z4, IFNULL(SUM(CASE WHEN a.VehicleClass=25 THEN a.CarNum ELSE 0 END),0) z5, IFNULL(SUM(CASE WHEN a.VehicleClass=26 THEN a.CarNum ELSE 0 END),0) z6, IFNULL(SUM(CASE WHEN a.VehicleClass IN (21,22,23,24,25,26) THEN a.CarNum ELSE 0 END),0) zsum, IFNULL(SUM(CASE WHEN a.VehicleClass IN (1,2,3,4,11,12,13,14,15,16,21,22,23,24,25,26) THEN a.CarNum ELSE 0 END),0) total FROM
SELECT * FROM ${tableName} AS alias${index + 1}
AND CancelFlag = 0 AND PayMode=0 AND SUBSTRING(LaneID,-4,1)=0 AND SUBSTRING(LaneID,-3,1)=1 AND StationID in
#{stationId}
AND StaDate >= #{intBeginTime}
AND StaDate <= #{intEndTime}
a
GROUP BY StaDate ORDER BY StaDate ASC
GROUP BY monthDate ORDER BY monthDate ASC
GROUP BY StationID ORDER BY StationID ASC
